-- MP-0023: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin if not exists(select 1 from public.entities where slug='barisan-nasional' and type='alliance') then raise exception 'MP-0023: missing party alliance'; end if; if exists(select 1 from public.entities where slug='mic' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='barisan-nasional'))) then raise exception 'MP-0023: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'mic','Malaysian Indian Congress','MIC','government','A component party of Barisan Nasional (BN).','2026-11-09','[{"label": "MIC · official representative and deputy president", "url": "https://mic.org.my/member-of-parliament/"}, {"label": "MIC · current BN campaign, 5 November 2026", "url": "https://www.melakahariini.my/nadarajah-bukan-orang-baharu-dalam-khidmat-masyarakat-dun-gadek/"}, {"label": "SPR · registered party symbols, October 2025", "url": "https://spr.gov.my/wp-content/uploads/2025/11/SIMBOL-PARTI-YANG-BERDAFTAR-DENGAN-SPR-SEHINGGA-30-OKTOBER-2025.pdf"}]'::jsonb from public.entities parent where parent.slug='barisan-nasional' and parent.type='alliance' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0023: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='mic' and type='party') then raise exception 'MP-0023: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0023: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('chong-zhemin','tan-kar-hing','saravanan-murugan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0023: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kampar','gopeng','tapah') and slug not in ('chong-zhemin','tan-kar-hing','saravanan-murugan')) then raise exception 'MP-0023: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0023:%' and (m.source_type <> 'editorial' or e.slug not in ('chong-zhemin','tan-kar-hing','saravanan-murugan') or m.import_key not like 'MP-0023:' || e.slug || ':%')) then raise exception 'MP-0023: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'chong-zhemin','Chong Zhemin','government','Member of the Dewan Rakyat','Kampar','Perak','Chong Zhemin represents Kampar, Perak, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4109','/portraits/chong-zhemin.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P070.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4109"}, {"label": "DAP · current Perak representatives", "url": "https://dapmalaysia.org/perak-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'tan-kar-hing','Tan Kar Hing','government','Member of the Dewan Rakyat','Gopeng','Perak','Tan Kar Hing represents Gopeng, Perak, in the Dewan Rakyat. A PKR member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4110','/portraits/tan-kar-hing.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P071.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4110"}, {"label": "PKR · current representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'saravanan-murugan','Saravanan Murugan','government','Member of the Dewan Rakyat; Deputy President of MIC','Tapah','Perak','Saravanan Murugan represents Tapah, Perak, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; Deputy President of MIC. A MIC member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4111','/portraits/saravanan-murugan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P072.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4111"}, {"label": "MIC · parliamentary representative and deputy president", "url": "https://mic.org.my/member-of-parliament/"}, {"label": "MIC · current BN campaign, 5 November 2026", "url": "https://www.melakahariini.my/nadarajah-bukan-orang-baharu-dalam-khidmat-masyarakat-dun-gadek/"}]'::jsonb from public.entities parent where parent.slug='mic' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('chong-zhemin','tan-kar-hing','saravanan-murugan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0023: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0023:tan-kar-hing:temu-rakyat-launch','Hold the first Gopeng Temu Rakyat service programme','Community Development','achieved',null,null,null,null,'2026-01-31','https://www.bernama.com/bm/am/news.php?id=2518839','Tan’s constituency programme brought government service counters and complaints channels to Sungai Rapat, with ten participating agencies.','Achieved covers the first event only. Expansion to Teja and Simpang Pulai and resolution of every complaint are separate, unverified outcomes.','2026-11-09','editorial',false from public.entities e where e.slug='tan-kar-hing' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0023:tan-kar-hing:gopeng-tamil-school','Advance preparations for a replacement Gopeng Tamil school building','Education',null,null,null,'2025-11-18','https://varnam.my/111967/long-damaged-gopeng-tamil-school-set-for-rebuild-says-tan-kar-hing/',null,null,'Tan announced preparations for a new building after federal funding approval following his earlier request.','The allocation and preparation announcement do not establish a finished building. A March 2026 report separately described a 22-month construction schedule; no completion percentage or exact final date is inferred.','2026-11-09','editorial',false from public.entities e where e.slug='tan-kar-hing' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

